import java.util.Scanner;

public class Main {
    static int n_value, k_value, mod_value;
    static long[] factorials = new long[250004];
    static long[] invs = new long[250004];
    static long[][] cache = new long[27][250004];

    static int lowbit(int x) {
        return x & (-x);
    }

    static long fast_pow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod_value;
            base = (base * base) % mod_value;
            exp >>= 1;
        }
        return result;
    }

    static void setup() {
        factorials[0] = 1;
        for (int i = 1; i <= n_value; ++i)
            factorials[i] = (factorials[i - 1] * i) % mod_value;
        invs[n_value] = fast_pow(factorials[n_value], mod_value - 2);
        for (int i = n_value - 1; i >= 0; --i)
            invs[i] = (invs[i + 1] * (i + 1)) % mod_value;
    }

    static long solve(int x, int s) {
        if (cache[x][s] != -1) return cache[x][s];
        if (s == 0) return cache[x][s] = (factorials[n_value] * factorials[k_value]) % mod_value * invs[k_value - x] % mod_value;
        int remaining = s - lowbit(s);
        long sum = 0;
        for (int t = remaining; t != 0; t = (t - 1) & remaining)
            sum = (sum + solve(x + 1, t) * invs[s - t]) % mod_value;
        sum = (sum + solve(x + 1, 0) * invs[s]) % mod_value;
        return cache[x][s] = sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n_value = sc.nextInt();
        k_value = sc.nextInt();
        mod_value = sc.nextInt();
        setup();
        long ans = fast_pow(k_value, n_value);
        if (n_value % 2 == 0) {
            for (int i = 0; i < 27; ++i)
                for (int j = 0; j <= n_value; ++j)
                    cache[i][j] = -1;
            ans = (ans - solve(0, n_value) + mod_value) % mod_value;
        }
        System.out.println(ans);
        sc.close();
    }
}
